@@ -0,0 +1,92 @@
+import { logError } from "../lib/log";
+import { handleSendLoopsTransactional } from "../lib/sendLoopsTransactional";
+import { type StripeInvoice } from "../lib/stripe-types";
+import { isEmail } from "../lib/validators/helpers";
+import * as TeamQueries from "../queries/team";
+
+async function getPdfBase64FromUrl(url: string): Promise<string> {
+  const response = await fetch(url);
+  return Buffer.from(await response.arrayBuffer()).toString("base64");
+}
+
+export default async function processStripeInvoicePaid(invoice: StripeInvoice) {
+  if (
+    invoice.parent?.type !== "subscription_details" ||
+    !invoice.parent.subscription_details
+  ) {
+    return;
+  }
+  const subscriptionInfo = invoice.parent.subscription_details.subscription;
+  const hostedInvoiceUrl = invoice.hosted_invoice_url;
+
+  const invoicePDFUrl = invoice.invoice_pdf;
+  const invoicePDFPromise = invoicePDFUrl
+    ? getPdfBase64FromUrl(invoicePDFUrl)
+    : null;
+
+  if (!hostedInvoiceUrl) return;
+  if (!subscriptionInfo) {
+    logError(
+      new Error(`Invoice[${invoice.id}] is not associated with a subscription`)
+    );
+    return;
+  }
+  const subscriptionId =
+    typeof subscriptionInfo === "string"
+      ? subscriptionInfo
+      : subscriptionInfo.id;
+
+  const associatedTeamId =
+    invoice.parent.subscription_details.metadata?.team_id;
+
+  const teams = await TeamQueries.findByIdOrSubscriptionId(
+    associatedTeamId,
+    subscriptionId
+  );
+  if (teams.length === 0) {
+    logError(
+      new Error(`Could not find associated team on Invoice[${invoice.id}]`)
+    );
+    return;
+  } else if (teams.length > 1) {
+    logError(
+      new Error(
+        `Too many teams matching Invoice[${invoice.id}]: ${teams
+          .map(({ id }) => id)
+          .join("|")}`
+      )
+    );
+    return;
+  }
+  const emails = teams[0].billingReceiptDestinations;
+  if (emails.some((e) => !isEmail(e))) {
+    logError(new Error(`Invalid destination emails on Team[${teams[0].id}]`));
+    return;
+  }
+
+  let invoicePDF = "";
+  if (invoicePDFPromise) {
+    invoicePDF = await invoicePDFPromise;
+  }
+
+  for (const email of emails) {
+    await handleSendLoopsTransactional({
+      transactionalId: process.env.TRANSACTIONAL_ID_INVOICE_PAID || "",
+      attachments:
+        invoicePDF !== ""
+          ? [
+              {
+                filename: "invoice.pdf",
+                contentType: "application/pdf",
+                data: invoicePDF,
+              },
+            ]
+          : [],
+      email,
+      dataVariables: {
+        invoiceUrl: hostedInvoiceUrl,
+        teamName: escape(teams[0].name ?? "connected"),
+      },
+    });
+  }
+}

